const listCalendarEventsIn = `-- name: ListCalendarEventsIn :many

SELECT id, name_en, name_ne, from_date, to_date, kind, built_in, created_by_user_id, key, approximate, created_at, updated_at FROM calendar_events
WHERE from_date <= $1 AND to_date >= $2
ORDER BY from_date, name_en, id
`

type ListCalendarEventsInParams struct {
	ToDay   pgtype.Date `json:"to_day"`
	FromDay pgtype.Date `json:"from_day"`
}

// Calendar --------------------------------------------------------------------
func (q *Queries) ListCalendarEventsIn(ctx context.Context, arg ListCalendarEventsInParams) ([]CalendarEvent, error) {
	rows, err := q.db.Query(ctx, listCalendarEventsIn, arg.ToDay, arg.FromDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CalendarEvent{}
	for rows.Next() {
		var i CalendarEvent
		if err := rows.Scan(
			&i.ID,
			&i.NameEn,
			&i.NameNe,
			&i.FromDate,
			&i.ToDate,
			&i.Kind,
			&i.BuiltIn,
			&i.CreatedByUserID,
			&i.Key,
			&i.Approximate,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

